    sendMessage: {
        parameters: {
            query?: never;
            header?: {
                /**
                 * @description 客户端生成的去重键。同一个会话里带同一个键重复提交时，
                 *     服务端不重新执行生成，而是把该轮已记录的事件补发出来，
                 *     并以该轮的 done / error 帧收尾。
                 *
                 *     省略这个头时行为与没有幂等能力时完全一样（每次都重新生成）。
                 *     同一个键配不同的正文会返回 invalid_argument 的错误帧，
                 *     而不是把上一轮的回答重放一遍。
                 */
                "Idempotency-Key"?: string;
            };
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["SendMessageRequest"];
            };
        };
        responses: {
            /** @description SSE 流开始。之后的成功/失败都通过流内事件表达 （token/citation/error/done），不再改变这个 200。 */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/event-stream": string;
                };
            };
            400: components["responses"]["InvalidArgument"];
            404: components["responses"]["NotFound"];
            500: components["responses"]["InternalError"];
        };
    };
    subscribeConversationEvents: {
        parameters: {
            query?: {
                /** @description 只返回这个 id 之后的事件；省略或传 0 表示从头开始 */
                after_event_id?: number;
            };
            header?: never;
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /**
             * @description SSE 流。把 event_id > after_event_id 的事件补发一遍，然后结束响应。
             *     【它不持有连接等新事件】——那条承诺从来没有被实现，本地单机场景
             *     下也没有意义。要看某一轮后续的内容用 POST messages 的幂等键补发
             *     （见 docs/sse-protocol.md「幂等与断线的闭环」）。
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/event-stream": string;
                };
            };
            500: components["responses"]["InternalError"];
        };
    };
